import{c as r,Q as d,j as a,m as o}from"./chunks/framework.B2dUnTNU.js";const c=JSON.parse('{"title":"农业 2.0","description":"","frontmatter":{},"headers":[],"relativePath":"b42/farming.md","filePath":"b42/farming.md","lastUpdated":1779624442000}'),n={name:"b42/farming.md"};function s(e,t,l,i,h,g){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="农业-2-0" tabindex="-1">农业 2.0 <a class="header-anchor" href="#农业-2-0" aria-label="Permalink to &quot;农业 2.0&quot;">​</a></h1><p>B42 的农业系统从&quot;挖坑撒种等收&quot;变成了<strong>真正需要思考和规划的农耕模拟</strong>。对 B41 老玩家来说，这是最大的玩法改变之一。</p><div class="danger custom-block"><p class="custom-block-title">B41 经验不再适用</p><p>B41 的&quot;随便种种就能活&quot;不适用了。B42 种错过季节的作物会颗粒无收。</p></div><hr><h2 id="⚠️-b41-→-b42-核心变化" tabindex="-1">⚠️ B41 → B42 核心变化 <a class="header-anchor" href="#⚠️-b41-→-b42-核心变化" aria-label="Permalink to &quot;⚠️ B41 → B42 核心变化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变化</th><th>B41</th><th>B42</th></tr></thead><tbody><tr><td><strong>季节系统</strong></td><td>无，全年可种</td><td>每种作物有特定种植季节</td></tr><tr><td><strong>室内种植</strong></td><td>可</td><td>反季节室内种植也会失败（室内绿植除外）</td></tr><tr><td><strong>生长时间</strong></td><td>固定天数</td><td>受温度、日照、降雨综合影响</td></tr><tr><td><strong>种子品种</strong></td><td>7 种作物</td><td>50+ 种子品种</td></tr><tr><td><strong>害虫</strong></td><td>无</td><td>蛞蝓、蜗牛攻击作物</td></tr><tr><td><strong>杂草</strong></td><td>无</td><td>需定期除草</td></tr><tr><td><strong>操作方式</strong></td><td>右键菜单</td><td>&quot;星露谷化&quot;——锄头战斗姿态挖沟，种子在手按交互键播种</td></tr></tbody></table><hr><h2 id="季节系统" tabindex="-1">季节系统 <a class="header-anchor" href="#季节系统" aria-label="Permalink to &quot;季节系统&quot;">​</a></h2><p>每种作物只有在<strong>正确的季节</strong>才能生长。种错季节 = 白种。</p><h3 id="按季节划分" tabindex="-1">按季节划分 <a class="header-anchor" href="#按季节划分" aria-label="Permalink to &quot;按季节划分&quot;">​</a></h3><table tabindex="0"><thead><tr><th>季节</th><th>推荐种植</th></tr></thead><tbody><tr><td><strong>春季</strong> 🌱</td><td>豌豆、大蒜、亚麻、大麦、啤酒花、烟草、大部分香草</td></tr><tr><td><strong>夏季</strong> ☀️</td><td>玉米、番茄、向日葵、辣椒、大部分蔬菜</td></tr><tr><td><strong>秋季</strong> 🍂</td><td>黑麦、土豆、洋葱、胡萝卜、甜菜</td></tr><tr><td><strong>冬季</strong> ❄️</td><td>几乎无法户外种植——依赖储存食物过冬</td></tr></tbody></table><h3 id="冬季生存策略" tabindex="-1">冬季生存策略 <a class="header-anchor" href="#冬季生存策略" aria-label="Permalink to &quot;冬季生存策略&quot;">​</a></h3><ul><li>冬季成为真正的<strong>食物短缺威胁</strong></li><li>必须在春夏秋三季积累足够的<strong>腌制/烟熏/干制</strong>食物</li><li>制陶（储存罐）和烹饪（食物保存）技能在冬天的价值飙升</li></ul><hr><h2 id="新作物与用途链" tabindex="-1">新作物与用途链 <a class="header-anchor" href="#新作物与用途链" aria-label="Permalink to &quot;新作物与用途链&quot;">​</a></h2><p>B42 新增了 <strong>50+ 种子品种</strong>，以下是最重要的新作物：</p><table tabindex="0"><thead><tr><th>作物</th><th>主要用途</th><th>联动技能</th></tr></thead><tbody><tr><td>🌿 <strong>大麦</strong></td><td>酿造啤酒</td><td>酿酒（开发中）</td></tr><tr><td>🌿 <strong>啤酒花</strong></td><td>酿造啤酒</td><td>酿酒（开发中）</td></tr><tr><td>🧵 <strong>亚麻</strong></td><td>制作亚麻线</td><td>裁缝</td></tr><tr><td>🪢 <strong>工业大麻</strong></td><td>制绳、布料、榨油</td><td>裁缝/烹饪</td></tr><tr><td>🍬 <strong>甜菜</strong></td><td>制糖或乙醇</td><td>烹饪/燃料</td></tr><tr><td>🌻 <strong>向日葵</strong></td><td>榨食用油</td><td>烹饪</td></tr><tr><td>🚬 <strong>烟草</strong></td><td>自种香烟 → 供给吸烟者特征</td><td>—</td></tr><tr><td>🌿 <strong>迷迭香</strong></td><td>驱虫（种旁边防蛞蝓）、药用</td><td>烹饪/医疗</td></tr><tr><td>🌽 <strong>玉米</strong></td><td>主食、饲料</td><td>畜牧</td></tr><tr><td>🧄 <strong>大蒜</strong></td><td>可作种子直接种、烹饪</td><td>烹饪</td></tr></tbody></table><h3 id="关键联动" tabindex="-1">关键联动 <a class="header-anchor" href="#关键联动" aria-label="Permalink to &quot;关键联动&quot;">​</a></h3><ul><li><strong>土豆/洋葱/大蒜</strong> → 本身就能当种子用（不用专门找种子包）</li><li><strong>烟草</strong> → 有吸烟者特征的玩家可以<strong>自种香烟</strong>，不再完全依赖搜刮</li><li><strong>香草</strong> → 可反复收割，可能驱虫或有药用效果</li><li><strong>大麦+啤酒花</strong> → 酿酒联动（酿酒功能上线后）</li><li><strong>亚麻+大麻</strong> → 裁缝/制绳，闭合衣物生产循环</li></ul><hr><h2 id="害虫与疾病" tabindex="-1">害虫与疾病 <a class="header-anchor" href="#害虫与疾病" aria-label="Permalink to &quot;害虫与疾病&quot;">​</a></h2><h3 id="威胁一览" tabindex="-1">威胁一览 <a class="header-anchor" href="#威胁一览" aria-label="Permalink to &quot;威胁一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>威胁</th><th>表现</th><th>对策</th></tr></thead><tbody><tr><td>🐌 <strong>蛞蝓/蜗牛</strong></td><td>啃食作物，降低产量</td><td>① 商品杀虫剂 ② 种迷迭香在旁边 ③ 散养鸡吃虫</td></tr><tr><td>🌿 <strong>杂草</strong></td><td>与作物争夺养分</td><td>定期手动除草</td></tr><tr><td>🦠 <strong>病害</strong></td><td>霉菌、枯萎等</td><td>及时移除病株防止扩散</td></tr></tbody></table><h3 id="生态闭环" tabindex="-1">生态闭环 <a class="header-anchor" href="#生态闭环" aria-label="Permalink to &quot;生态闭环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>鸡吃害虫 → 鸡产蛋/粪 → 粪肥田 → 作物健壮 → 次品作物喂猪 → 猪肉</span></span></code></pre></div><hr><h2 id="操作改善" tabindex="-1">操作改善 <a class="header-anchor" href="#操作改善" aria-label="Permalink to &quot;操作改善&quot;">​</a></h2><p>B42 的农耕操作被社区戏称为&quot;星露谷物语化&quot;：</p><ol><li><strong>装备锄头</strong> → 进入战斗姿态 → 即可挖掘犁沟（不再是右键菜单）</li><li><strong>种子拿在手上</strong> → 对准犁沟按交互键 → 播种</li><li>犁沟和作物生长阶段有<strong>可视化反馈</strong>，比 B41 直观得多</li></ol><div class="tip custom-block"><p class="custom-block-title">新手建议</p><p>第一季先少种几排练手，掌握季节+害虫管理后再大规槿扩产。错过一季就是几个月没吃的。</p></div><hr><h2 id="b41-作物在-b42-的状态" tabindex="-1">B41 作物在 B42 的状态 <a class="header-anchor" href="#b41-作物在-b42-的状态" aria-label="Permalink to &quot;B41 作物在 B42 的状态&quot;">​</a></h2><p>B41 的 7 种基础作物（土豆、胡萝卜、番茄、卷心菜、西兰花、草莓、萝卜）仍然存在，但：</p><ul><li>每种都有了特定的<strong>种植季节</strong></li><li>生长速度受环境因素影响，不再是固定天数</li><li>疾病风险比 B41 高</li></ul>',34)])])}const u=r(n,[["render",s]]);export{c as __pageData,u as default};
